# Generated by the network debugging agent
# Request: measure latency and jitter from ns1 to ns2
# TYPE: one-sided
# Re-run: python tool_builder.py --run tools/latency_jitter.py
#!/usr/bin/env python3
"""Measure latency and jitter from ns1 (10.0.0.1) to ns2 (10.0.0.2) via ping."""
import re
import subprocess
import sys
import statistics

TARGET = "10.0.0.2"
COUNT = 20
INTERVAL = "0.2"
PER_PACKET_TIMEOUT = "1"
DEADLINE = "15"
SUBPROCESS_TIMEOUT = 20

def run_ping(args):
    """Run ping with timeout, return CompletedProcess or None on timeout."""
    try:
        result = subprocess.run(
            args,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=SUBPROCESS_TIMEOUT,
        )
        return result
    except FileNotFoundError as e:
        print(f"[ERROR] ping binary not found: {e}")
        return None
    except subprocess.TimeoutExpired:
        print(f"[ERROR] ping subprocess timed out after {SUBPROCESS_TIMEOUT}s")
        return None

def parse_rtts(output):
    """Extract per-packet RTTs in ms from ping output."""
    rtts = []
    for m in re.finditer(r"time=([0-9.]+)\s*ms", output):
        try:
            rtts.append(float(m.group(1)))
        except ValueError:
            continue
    return rtts

def parse_summary(output):
    """Extract transmitted/received/loss and rtt line as raw strings."""
    tx = rx = loss = None
    m = re.search(
        r"(\d+)\s+packets transmitted,\s+(\d+)\s+(?:packets\s+)?received.*?(\d+(?:\.\d+)?)%\s+packet loss",
        output,
    )
    if m:
        tx = int(m.group(1))
        rx = int(m.group(2))
        loss = float(m.group(3))
    rtt_line = None
    m2 = re.search(r"rtt min/avg/max/mdev\s*=\s*([0-9./]+)\s*ms", output)
    if m2:
        rtt_line = m2.group(0)
    else:
        # alternative format: round-trip min/avg/max/stddev
        m3 = re.search(r"(?:round-trip|rtt)[^\n=]*=\s*([0-9./]+)\s*ms", output)
        if m3:
            rtt_line = m3.group(0)
    summary_line = None
    for line in output.splitlines():
        if "packets transmitted" in line:
            summary_line = line.strip()
            break
    return tx, rx, loss, rtt_line, summary_line

def compute_jitter(rtts):
    """Return dict with jitter stats."""
    if len(rtts) < 2:
        return {}
    diffs = [abs(rtts[i] - rtts[i-1]) for i in range(1, len(rtts))]
    mean_diff = sum(diffs) / len(diffs)
    # RFC 3550 interarrival jitter approximation on RTTs
    j = 0.0
    for d in diffs:
        j += (d - j) / 16.0
    stats = {
        "samples": len(rtts),
        "mean_abs_diff_ms": mean_diff,
        "rfc3550_jitter_ms": j,
        "max_abs_diff_ms": max(diffs),
        "min_abs_diff_ms": min(diffs),
    }
    if len(rtts) >= 2:
        try:
            stats["stdev_ms"] = statistics.stdev(rtts)
        except statistics.StatisticsError:
            stats["stdev_ms"] = 0.0
        try:
            stats["pstdev_ms"] = statistics.pstdev(rtts)
        except statistics.StatisticsError:
            stats["pstdev_ms"] = 0.0
    return stats

def main():
    print(f"[INFO] Target: {TARGET} (ns2) from ns1")
    print(f"[INFO] Tool: ping -4 -n -c {COUNT} -i {INTERVAL} -W {PER_PACKET_TIMEOUT} -w {DEADLINE} {TARGET}")
    print(f"[INFO] Expect ~{COUNT} samples for latency + jitter")

    args = ["ping", "-4", "-n", "-c", str(COUNT), "-i", INTERVAL,
            "-W", PER_PACKET_TIMEOUT, "-w", DEADLINE, TARGET]
    result = run_ping(args)

    # Fallback if -i 0.2 not permitted for normal user: retry without -i
    if result is not None and result.returncode != 0:
        combined = (result.stdout or "") + (result.stderr or "")
        if "permission" in combined.lower() or "cannot" in combined.lower() or "bad timing" in combined.lower():
            print("[WARN] ping with -i 0.2 failed, retrying with default interval (count 10)")
            args2 = ["ping", "-4", "-n", "-c", "10", "-W", PER_PACKET_TIMEOUT, "-w", DEADLINE, TARGET]
            print(f"[INFO] Retry tool: {' '.join(args2)}")
            result2 = run_ping(args2)
            if result2 is not None:
                result = result2

    if result is None:
        print("[RESULT] status: ERROR ping could not run")
        print("[EVIDENCE] no ping output (binary missing or subprocess timeout)")
        return 0

    output = (result.stdout or "") + (("\n" + result.stderr) if result.stderr else "")
    print(f"[INFO] ping exit code: {result.returncode}")

    # Raw evidence
    print("---- RAW PING OUTPUT BEGIN ----")
    print(output.strip() if output.strip() else "(empty output)")
    print("---- RAW PING OUTPUT END ----")

    rtts = parse_rtts(result.stdout or "")
    tx, rx, loss, rtt_line, summary_line = parse_summary(result.stdout or "")

    # Fallback: try parsing combined output if stdout parse failed
    if tx is None:
        tx2, rx2, loss2, rtt_line2, summary_line2 = parse_summary(output)
        tx, rx, loss = tx2, rx2, loss2
        if rtt_line is None:
            rtt_line = rtt_line2
        if summary_line is None:
            summary_line = summary_line2

    print(f"[EVIDENCE] ping summary line: {summary_line if summary_line else 'NOT FOUND'}")
    print(f"[EVIDENCE] ping rtt line: {rtt_line if rtt_line else 'NOT FOUND'}")
    print(f"[EVIDENCE] packets transmitted: {tx if tx is not None else 'unknown'}")
    print(f"[EVIDENCE] packets received: {rx if rx is not None else 'unknown'}")
    print(f"[EVIDENCE] packet loss %: {loss if loss is not None else 'unknown'}")
    print(f"[EVIDENCE] rtt samples collected: {len(rtts)} / {COUNT}")
    if rtts:
        print(f"[EVIDENCE] per-packet RTTs (ms): {', '.join(f'{v:.3f}' for v in rtts)}")
    else:
        print("[EVIDENCE] per-packet RTTs (ms): none")

    if not rtts:
        print("[RESULT] status: FAIL no replies (100% loss or host unreachable)")
        print(f"[RESULT] latency: no data (tx={tx} rx={rx} loss={loss})")
        print("[RESULT] jitter: no data (need >=2 replies)")
        return 0

    # Latency stats from our samples (authoritative) + ping's own line for cross-check
    mn = min(rtts)
    mx = max(rtts)
    avg = sum(rtts) / len(rtts)
    print(f"[RESULT] replies: {len(rtts)}/{tx if tx is not None else COUNT} received")
    print(f"[RESULT] latency min/avg/max (ms, computed from {len(rtts)} samples): {mn:.3f}/{avg:.3f}/{mx:.3f}")
    if len(rtts) >= 2:
        try:
            sd = statistics.stdev(rtts)
        except statistics.StatisticsError:
            sd = 0.0
        print(f"[RESULT] latency stdev (ms): {sd:.3f}")
        print(f"[RESULT] latency sorted (ms): {', '.join(f'{v:.3f}' for v in sorted(rtts))}")
    if rtt_line:
        print(f"[RESULT] ping-reported rtt line: {rtt_line}")

    if len(rtts) >= 2:
        j = compute_jitter(rtts)
        print(f"[RESULT] jitter mean-abs-successive-diff (ms): {j['mean_abs_diff_ms']:.3f}")
        print(f"[RESULT] jitter RFC3550-estimate (ms): {j['rfc3550_jitter_ms']:.3f}")
        print(f"[RESULT] jitter min/max successive diff (ms): {j['min_abs_diff_ms']:.3f}/{j['max_abs_diff_ms']:.3f}")
        print(f"[RESULT] jitter stdev/pstdev (ms): {j['stdev_ms']:.3f}/{j['pstdev_ms']:.3f}")
        diffs = [abs(rtts[i] - rtts[i-1]) for i in range(1, len(rtts))]
        print(f"[EVIDENCE] successive |RTT[i]-RTT[i-1]| (ms): {', '.join(f'{v:.3f}' for v in diffs)}")
        print("[RESULT] status: OK latency and jitter measured")
    else:
        print("[RESULT] jitter: no data (need >=2 replies for jitter)")
        print("[RESULT] status: PARTIAL only 1 reply, latency measured, jitter unavailable")

    return 0

if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception as e:
        # Real bug: allow crash (non-zero) but print what happened
        print(f"[FATAL] unexpected bug: {e!r}")
        raise
